import json
from typing import List, Dict, Any

# Lista para almacenar los IDs de RAGFlow extraídos
ragflow_ids: List[str] = []

try:
    docs_to_process = _input.all()
    if not docs_to_process:
        raise IndexError("Input list is empty.")

    for item in docs_to_process:

        item_data = item.get("json", {})
        is_activated = item_data.get("activation_required", False)
        doc_id = item_data.get("ragflow_id")

        if is_activated and doc_id:
            ragflow_ids.append(doc_id)

    return [{
        "json": {
            "docs_to_process": ragflow_ids
        }
    }]

except IndexError:
    return [{
        "json": {
            "error": "Input data is empty. No documents were passed to parse IDs.",
            "docs_to_process": []
        }
    }]

except Exception as e:
    return [{
        "json": {
            "error": f"Error during RAGFlow ID aggregation loop: {str(e)}",
            "docs_to_process": []
        }
    }]

import json
from typing import List, Dict, Any

# Lista para almacenar los items de salida formateados
try:
    input_data = _input.all()[0].get("json", {})
except IndexError:
    return [{"json": {"error": "Invalid input structure: Input list is empty."}}]
except Exception as e:
    return [{"json": {"error": f"Error, inccorrect data structura: {str(e)}"}}]

docs_to_process = []
input_data = _input.all()[0].get("json", {}).get("data",{})

for item in input_data:
    try:
        ragflow_response: Dict[str, Any] = item.to_py()
        ragflow_id = ragflow_response.get("doc_id") or ragflow_response.get("id")
        doc_name = ragflow_response.get("name") or item.get("json", {}).get("file_name") 
        initial_state = ragflow_response.get("run") or ragflow_response.get("status")

        if ragflow_id and doc_name and initial_state:

            docs_to_process.append({

                "json": {
                    "ragflow_id": ragflow_id,
                    "file_name": doc_name,
                    "activation_required": True 
                }
            })

        else:

            docs_to_process.append({
                "json": {
                    "error": "Missing critical IDs from RAGFlow response.",
                    "response_data": ragflow_response,
                    "file_name": doc_name,
                    "activation_required": False
                }
            })

    except Exception as e:

        docs_to_process.append({
            "json": {
                "error": f"Error during parsing RAGFlow response: {str(e)}",
                "file_name": item.get("json", {}).get("file_name", "UNKNOWN"),
                "activation_required": False
            }
        })

return docs_to_process
